package com.on.ebx.connect.connectors;

import java.io.*;import java.net.*;import java.util.*;import java.util.concurrent.atomic.*;
import com.fasterxml.jackson.databind.JsonNode;import com.sun.net.httpserver.*;import com.on.ebx.connect.spi.*;

/** Offline signed HTTP fixture for bounded, explicitly acknowledged SQS behavior. */
public final class SqsConnectorTest
{
	public static void main(final String[] args)throws Exception
	{System.setProperty("ebx.connectors.aws.accessKeyId","AKIDTEST");System.setProperty("ebx.connectors.aws.secretAccessKey","secret");final AtomicReference<String> action=new AtomicReference<String>();final HttpServer server=HttpServer.create(new InetSocketAddress("127.0.0.1",0),0);server.createContext("/queue",x->{final String body=read(x.getRequestBody());action.set(body);check(x.getRequestHeaders().getFirst("Authorization").contains("/sqs/aws4_request"),"SigV4 service");final String answer=body.contains("ReceiveMessage")?"<ReceiveMessageResponse><Message><MessageId>m1</MessageId><ReceiptHandle>rh1</ReceiptHandle><Body>A&amp;B</Body></Message></ReceiveMessageResponse>":body.contains("DeleteMessage")?"<DeleteMessageResponse/>":"<SendMessageResponse><MessageId>sent</MessageId></SendMessageResponse>";x.sendResponseHeaders(200,answer.length());x.getResponseBody().write(answer.getBytes("UTF-8"));x.close();});server.start();try{final String url="http://127.0.0.1:"+server.getAddress().getPort()+"/queue";final SqsConnector c=new SqsConnector();final ConnectorConfig cfg=new ConnectorConfig();cfg.setId("sqs-test");cfg.setType("amazon-sqs");cfg.setProperty("queueUrl",url);cfg.setProperty("region","us-east-1");c.configure(cfg);JsonNode result=c.execute(null,"send",map("message","hello"),null);check("sent".equals(result.get("messageId").asText()),"send");result=c.execute(null,"receive",map("max","2","waitSeconds","1","visibilitySeconds","45"),null);check(result.size()==1&&"A&B".equals(result.get(0).get("body").asText()),"receive parse");check(!action.get().contains("DeleteMessage"),"receive deleted implicitly");c.execute(null,"peek",Collections.<String,String>emptyMap(),null);check(action.get().contains("VisibilityTimeout=0")&&action.get().contains("WaitTimeSeconds=0"),"peek safety");c.execute(null,"ack",map("receiptHandle","rh1"),null);check(action.get().contains("DeleteMessage")&&action.get().contains("ReceiptHandle=rh1"),"explicit ack");boolean bounded=false;try{c.execute(null,"receive",map("max","11"),null);}catch(final ConnectorException e){bounded=true;}check(bounded,"receive bound");check(c.getDescriptor().getDescription().contains("never delete implicitly"),"descriptor safety");System.out.println("PASS: SQS signed send, bounded receive/peek, explicit ack, visibility, long-poll, and no implicit delete");}finally{server.stop(0);System.clearProperty("ebx.connectors.aws.accessKeyId");System.clearProperty("ebx.connectors.aws.secretAccessKey");}}
	private static Map<String,String> map(final String...v){final Map<String,String>m=new LinkedHashMap<String,String>();for(int i=0;i<v.length;i+=2)m.put(v[i],v[i+1]);return m;}private static String read(final InputStream in)throws IOException{final ByteArrayOutputStream out=new ByteArrayOutputStream();final byte[]b=new byte[1024];for(int n;(n=in.read(b))>=0;)out.write(b,0,n);return new String(out.toByteArray(),"UTF-8");}private static void check(final boolean b,final String m){if(!b)throw new AssertionError(m);}
}
